-- composition of rule kernels outer_join_simplification x redundant_order_keys (duckdb), template graft_exists
SELECT a2.c0 AS c0, '2024-01-01 00:00:00+00'::timestamptz AS c1 FROM ((SELECT * FROM tp WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 ORDER BY 3, 3) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 ORDER BY 3, 3) AS kb)) AS a1 JOIN (t0 AS a2 LEFT JOIN (t1 POSITIONAL JOIN tp) ON ((a2.c1 = tp.c1) AND TRUE)) ON ((a1.c0 = tp.c0) AND ('abc'::text NOT ILIKE '%\\%'::text))) QUALIFY (COUNT (*) OVER () = 1);
